from collections import OrderedDict

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    named_classes = {cls.__name__: cls for cls in classes}

    minimal = OrderedDict()

    for cls in classes:
        # handle duplicate classes
        if cls.__name__ in minimal:
            minimal.pop(cls.__name__)

        # handle dependent classes
        dep_classes = []
        for cls_name in named_classes:
            if named_classes[cls_name].dependsOn(cls):
                dep_classes.append(cls_name)

        dep_classes.reverse()  # pop depends first to avoid removing in the same iteration
        for cls_name in dep_classes:
            minimal.pop(cls_name)

    # if maximal, add maximal last
    if ordered_by_maximal(classes) and classes[-1].isMaximal():
        minimal[classes[-1].__name__] = classes[-1]

    return [named_classes[label] for label in minimal.keys()]

def ordered_by_maximal(classes):
    """Helper function to order classes by their maximal property"""

    return classes[::-1] if classes[-1].isMaximal() else classes

