def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """

    def process(interface):
        if isinstance(interface, Declaration):
            return [interface]
        elif isinstance(interface, tuple):
            return [process(i) for i in interface]
        elif isinstance(interface, type):
            return [process(i) for i in interface.attributes]
        else:
            raise ValueError("Unsupported interface type: " + str(interface))

    result = []
    for value in sequence:
        if isinstance(value, Declaration):
            result.append(value)
            continue
        elif isinstance(value, tuple):
            result.extend(process(value))
            continue
        elif isinstance(value, type):
            result.extend(process(value.attributes))
            continue
        else:
            raise ValueError("Unsupported value type: " + str(value))

    if output is not None:
        return result
    else:
        return [result]

