def _validate_labels(labels):
    from typing import Dict, Union

    class ValidationError(Exception):
        def __init__(self, msg: Dict[str, str]):
            err_messages = []
            for key, value in msg.items():
                err_messages.append({"'" + key + "'": value})
            super().__init__(err_messages)

    import re

    patterns = {
        "$$": pattern=re.compile("^[A-Za-z0-9_]*$", re.IGNORECASE),
        True: pattern=re.compile("^[a-zA-Z0-9_]*$", re.IGNORECASE),
    }

    for key, value in labels.items():
        if isinstance(value, list):
            for v in value:
                if not re.match(patterns[key], v):
                    raise ValidationError({
                        key: f'expected string or bytes-like object',
                    })
        else:
            if not re.match(patterns[key], value):
                raise ValidationError({
                    key: f'expected string or bytes-like object',
                })

