def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    for resource in app.manifest:
        if resource.spec is not None:
            if 'default_observer_schema' not in resource.spec:
               .Observer_schema = {
                    "type": "object",
                    "properties": {}
                }
                for field in resource.spec:
                    if isinstance(resource.spec[field], dict):
                        if 'default' in resource.spec[field]:
                            if 'type' not in resource.spec[field]:
                                raise ValueError("Field %s in %s must have a 'type'." % (field, resource.spec))
                            if resource.spec[field]['type'] not in ['string', 'number', 'boolean']:
                                raise ValueError("Field %s in %s must be a 'string', 'number' or 'boolean'." % (field, resource.spec))
                            if isinstance(resource.spec[field]['default'], dict):
                                raise ValueError("Field %s in %s must not contain nested dictionaries." % (field, resource.spec))
                            if 'default' not in resource.spec[field]:
                                raise ValueError("Field %s in %s must have a 'default'." % (field, resource.spec))
                            resource.spec['default_observer_schema']['properties'][field] = {
                                "type": resource.spec[field]['type'],
