def format(self, sql, params):
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
    contains the set of in-style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	The set of converted out-style parameters (:class:`dict` or
      :class:`list`).
    """
    if not isinstance(sql, str) and not isinstance(sql, bytes):
        raise TypeError("sql must be a str or bytes")
    if not isinstance(params, dict) and not isinstance(params, list):
        raise TypeError("params must be a dict or list")
    if isinstance(params, dict):
        style = self.SQLParams.in_style or "named"
        if style == "named":
            if not self.SQLParams.named_params and self.sqlparams.is_out_style:
                raise ValueError("out-style params cannot be used with a named parameter style")
            if not all(isinstance(k, str) for k in params):
                raise ValueError("all keys in params must be strings")
            return self.__sqlformat(sql, params), params
        elif style == "ordinal":
            if not self.SQLParams.ordinals:
                raise ValueError("ordinal params cannot be used with an ordinal parameter style")
            if not all(isinstance(k, int) for k in params):
                raise ValueError("all keys in params must be integers")
            return self.__sqlformat(sql, params), params
        else:
            raise ValueError("invalid SQLParams.in_style", self.SQLParams.in_style)
    else:
        style = self.SQLParams.in_style or "named"
        if style == "named":
            if not self.SQLParams.named_params:
                raise ValueError("out-style params cannot be used with a named parameter style")
            return self.__sqlformat(sql, params), list(params)
        elif style == "ordinal":
            if not self.SQLParams.ordinals:
                raise ValueError("ordinal params cannot be used with an ordinal parameter style")
            return self.__sqlformat(sql, params), list(params)
        else:
            raise ValueError("invalid SQLParams.in_style", self.SQLParams.in_style)

