        elif t.type == 'comment':
            if t.value:
                self.comment += t.value if self.comment else t.value
        elif t.type == 'textrun':
            self.text += t.value
        elif t.type == 'embedded':
            self.text += t.render()

        self.last_position += (self.height + t.height if t.height else 0)

    self.render_content(style)

