    temp_dir = Path(tmp_path)

    # The command to extract the archive to the temporary directory
    if filename:
        extract_command = ["tar", "-xzf", archive_path, "-C", temp_dir]
    else:
        extract_command = ["tar", "-xzf", archive_path]

    try:
        subprocess.run(extract_command, check=True)
    except subprocess.CalledProcessError as e:
        raise ValueError(f"Failed to extract archive: {e}")

    # The file repository URL
    repo_url = f"file://{temp_dir}"

