def parse_frequency(frequency):
    if frequency in (None, "always"):
        return None
    if not isinstance(frequency, str):
        raise ValueError("Frequency must be a string")

    try:
        value, unit = frequency.split()
        if unit.startswith('min'):
            scale = 60
        elif unit.startswith('h'):
            scale = 60 * 60
        elif unit.startswith('d'):
            scale = 60 * 60 * 24
        elif unit.startswith('w'):
            scale = 60 * 60 * 24 * 7
        else:
            raise ValueError(f"Unsupported unit for frequency: {unit}")

        return datetime.timedelta(seconds=int(value) * scale)
    except ValueError:
        raise ValueError(f"Invalid format for frequency: {frequency}")

