        raise ValueError("YAML file path is required")

    with open(yaml_file, 'r') as stream:
        try:
            data = yaml.safe_load(stream)
        except yaml.YAMLError as exc:
            raise InvalidYAMLDataError(exc, yaml_file) from exc

    if not ('data' in data and 'schemas' in data['data']):
        raise MissingDataError("Missing 'data' field in YAML file")

    if not data['data']['schemas']['ir']:
        raise MissingSchemaError("Missing 'ir' schema in YAML file")

    return data

